<?php
namespace Ishep\Http\Controllers;use Throwable;use DomainException;use Ishep\Bootstrap\Application as App;use Ishep\Http\{Request,Response};
final class PortalController
{public function __construct(private string $domain){}private function app():App{return App::instance();}private function uid():int{return(int)$this->app()->session()->get('user_id');}private function plural():string{return$this->domain==='career'?'careers':'bursaries';}private function fail(Throwable $e,string $to):Response{$this->app()->session()->flash('errors',['portal'=>[$e instanceof DomainException?$e->getMessage():'The portal action could not be completed safely.']]);return Response::redirect(url($to));}
public function index(Request $r):Response{return$this->app()->render('portals/index',['domain'=>$this->domain,'opportunities'=>$this->app()->portals()->publicList($this->domain,$r->query),'filters'=>$r->query,'professions'=>$this->app()->references()->professions(),'provinces'=>$this->app()->references()->provinces()]);}public function show(Request $r):Response{$o=$this->app()->portals()->opportunity($this->domain,(string)$r->get('reference'));return$o?$this->app()->render('portals/show',['domain'=>$this->domain,'opportunity'=>$o,'application'=>$this->uid()?$this->app()->portals()->applicationForUser($this->domain,(int)$o['id'],$this->uid()):null]):$this->app()->render('errors/404',[],404);}
public function manage(Request $r):Response{return$this->app()->render('portals/manage',['domain'=>$this->domain,'opportunities'=>$this->app()->portals()->opportunities($this->domain),'create'=>str_ends_with($r->path,'/create'),'professions'=>$this->app()->references()->professions(),'provinces'=>$this->app()->references()->provinces()]);}public function create(Request $r):Response{try{$ref=$this->app()->portalService()->createOpportunity($this->domain,$this->uid(),$r->input,$r->ip());$this->app()->session()->flash('status','Draft opportunity '.$ref.' created.');return Response::redirect(url('/admin/'.$this->plural()));}catch(Throwable $e){return$this->fail($e,'/admin/'.$this->plural().'/create');}}public function opportunityStatus(Request $r):Response{try{$this->app()->portalService()->opportunityStatus($this->domain,$this->uid(),(string)$r->get('reference'),(string)$r->get('status'),$r->ip());$this->app()->session()->flash('status','Opportunity status updated.');return Response::redirect(url('/admin/'.$this->plural()));}catch(Throwable $e){return$this->fail($e,'/admin/'.$this->plural());}}
public function apply(Request $r):Response{$o=$this->app()->portals()->opportunity($this->domain,(string)$r->get('reference'));if(!$o)return$this->app()->render('errors/404',[],404);return$this->app()->render('portals/apply',['domain'=>$this->domain,'opportunity'=>$o,'application'=>$this->app()->portals()->applicationForUser($this->domain,(int)$o['id'],$this->uid()),'profile'=>$this->app()->profiles()->byUserId($this->uid())]);}public function save(Request $r):Response{$opp=(string)$r->get('reference');try{$a=$this->app()->portalService()->saveApplication($this->domain,$this->uid(),$opp,$r->input,(string)$r->get('action')==='submit',$r->ip());$this->app()->session()->flash('status',(string)$r->get('action')==='submit'?'Application submitted.':'Draft saved.');return Response::redirect(url('/'.$this->plural().'/applications/'.$a['application_reference']));}catch(Throwable $e){return$this->fail($e,'/'.$this->plural().'/'.$opp.'/apply');}}
public function applications(Request $r):Response{$staff=str_starts_with($r->path,'/admin/');return$this->app()->render('portals/applications',['domain'=>$this->domain,'applications'=>$this->app()->portals()->applications($this->domain,$staff?null:$this->uid(),trim((string)($r->query['status']??''))?:null),'staff'=>$staff]);}public function application(Request $r):Response{$staff=str_starts_with($r->path,'/admin/');$a=$this->app()->portals()->application($this->domain,(string)$r->get('reference'),$staff?null:$this->uid());return$a?$this->app()->render('portals/application',['domain'=>$this->domain,'application'=>$a,'events'=>$this->app()->portals()->events($this->domain,(int)$a['id'],$staff),'staff'=>$staff]):$this->app()->render('errors/404',[],404);}
public function withdraw(Request $r):Response{try{$this->app()->portalService()->withdraw($this->domain,$this->uid(),(string)$r->get('reference'),$r->ip());$this->app()->session()->flash('status','Application withdrawn.');return Response::redirect(url('/'.$this->plural().'/applications/'.(string)$r->get('reference')));}catch(Throwable $e){return$this->fail($e,'/'.$this->plural().'/applications/'.(string)$r->get('reference'));}}public function review(Request $r):Response{try{$this->app()->portalService()->review($this->domain,$this->uid(),(string)$r->get('reference'),(string)$r->get('status'),(string)($r->input['decision_reason']??''),(string)($r->input['private_reviewer_note']??''),$r->ip());$this->app()->session()->flash('status','Application status updated.');return Response::redirect(url('/admin/'.$this->plural().'/applications/'.(string)$r->get('reference')));}catch(Throwable $e){return$this->fail($e,'/admin/'.$this->plural().'/applications/'.(string)$r->get('reference'));}}}
